contract InvMutTest {
    C c;
    uint public lastFrom;
    uint public lastTo;
    uint public lastVal;

    constructor(C _c) { c = _c; }

    function run(address from, uint v, uint n) public payable {
        require(n >= 0);
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(uint160(1000 + i));
        }
        bool ok = c.transfer(from, address(this), tos, v);
        assert(ok);
    }

    fallback() external payable {
        bytes4 tid = bytes4(keccak256("transferFrom(address,address,uint256)"));
        if (msg.sig == tid) {
            (address f, address t, uint val) = abi.decode(msg.data[4:], (address, address, uint256));
            lastFrom = uint160(f);
            lastTo = uint160(t);
            lastVal = val;
        }
    }

    receive() external payable {}
}

