contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address to, uint v) public payable {
        require(address(this).balance >= 0);
        bool ok;
        bool r;
        try c.transfer(from, caddress, toArray(to), v) returns (bool res) {
            ok = true;
            r = res;
        } catch {
            ok = false;
            r = false;
        }
        bool emptyReverted;
        address[] memory none = new address[](0);
        try c.transfer(from, caddress, none, v) {
            emptyReverted = false;
        } catch {
            emptyReverted = true;
        }
        assert(emptyReverted && (!ok || r));
    }
    function toArray(address a) internal pure returns (address[] memory arr) {
        arr = new address[](1);
        arr[0] = a;
    }
    receive() external payable {}
}

